<?php $publishedInstructors=[];try{$publishedInstructors=rows('SELECT * FROM instructors WHERE is_published=1'.(query('id')?' AND id=?':'').' ORDER BY name',query('id')?[(int)query('id')]:[]);}catch(Throwable $ex){error_log($ex->getMessage());} ?>
<section class="public-page" style="padding-top:20px"><div class="portal-grid"><?php foreach($publishedInstructors as $person): ?><article class="panel"><?php if($photo=safeUrl($person['photo'])): ?><img class="profile-photo" src="<?= e($photo) ?>" alt="<?= e($person['name']) ?>"><?php endif; ?><h2><?= e($person['name']) ?></h2><?php foreach(['bio'=>'Profil profesional','expertise'=>'Bidang keahlian','experience'=>'Pengalaman kerja','certifications'=>'Kualifikasi & sertifikasi','training_history'=>'Riwayat pelatihan'] as $key=>$label): ?><h3><?= $label ?></h3><p class="lesson-body"><?= e($person[$key]?:'Belum dipublikasikan') ?></p><?php endforeach; ?></article><?php endforeach; ?></div><?php if(query('id')&&!$publishedInstructors): ?><p class="notice info">Profil instruktur tidak ditemukan atau belum dipublikasikan.</p><?php endif; ?></section>
